{"op":"begin","version":1,"title":"三维交互示例","state":{"speed":0.4,"color":"#54a98a","cameraX":3,"cameraY":2,"cameraZ":5}}
{"op":"node","node":{"id":"scene","kind":"web","data":"{\"version\":1,\"library\":\"three\",\"height\":520,\"html\":\"<div id=\\\"stage\\\"></div><section><label>旋转速度 <input id=\\\"speed\\\" type=\\\"range\\\" min=\\\"0\\\" max=\\\"2\\\" step=\\\"0.1\\\"></label><label>颜色 <input id=\\\"color\\\" type=\\\"color\\\"></label><p id=\\\"status\\\">拖动旋转 · 双指缩放</p></section>\",\"css\":\"body{background:#f5f8f6}#stage{height:360px;width:100%}section{padding:16px;display:grid;gap:12px}label{display:flex;gap:12px;align-items:center;justify-content:space-between}input[type=range]{flex:1}#status{font-size:13px;margin:0;color:#456254}\",\"js\":\"const stage=document.getElementById('stage');\\nconst canvas=document.createElement('canvas');\\nconst gl=canvas.getContext('webgl2',{antialias:true});\\nif(!gl) throw new Error('此设备的 WebGL 2 不可用，无法展示三维场景。');\\nconst renderer=new THREE.WebGLRenderer({canvas,context:gl,antialias:true});\\nrenderer.setPixelRatio(Math.min(devicePixelRatio,2));stage.append(canvas);\\nconst scene=new THREE.Scene();scene.background=new THREE.Color('#f5f8f6');\\nconst camera=new THREE.PerspectiveCamera(42,1,0.1,100);\\nconst mesh=new THREE.Mesh(new THREE.TorusKnotGeometry(0.9,0.28,120,20),new THREE.MeshStandardMaterial({color:tinybot.state.color,roughness:0.3,metalness:0.2}));scene.add(mesh);\\nscene.add(new THREE.HemisphereLight(0xffffff,0x648077,2.2));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(3,5,4);scene.add(light);\\nconst controls=new OrbitControls(camera,canvas);controls.enableDamping=true;controls.minDistance=2.5;controls.maxDistance=12;\\nconst speed=document.getElementById('speed'),color=document.getElementById('color'),status=document.getElementById('status');let current=tinybot.state;\\nfunction apply(values){current=values;speed.value=values.speed;color.value=values.color;mesh.material.color.set(values.color);camera.position.set(values.cameraX,values.cameraY,values.cameraZ);controls.update();speed.disabled=!tinybot.active;color.disabled=!tinybot.active;}\\napply(current);tinybot.onState(apply);\\nfunction resize(){renderer.setSize(stage.clientWidth,stage.clientHeight);camera.aspect=stage.clientWidth/stage.clientHeight;camera.updateProjectionMatrix();renderer.render(scene,camera);}\\nnew ResizeObserver(resize).observe(stage);resize();\\nasync function save(patch){try{await tinybot.save({...tinybot.state,...patch});status.textContent='参数已应用';}catch(error){status.textContent=error.message;}}\\nspeed.addEventListener('change',()=>save({speed:Number(speed.value)}));color.addEventListener('change',()=>save({color:color.value}));\\ncontrols.addEventListener('end',()=>{if(tinybot.active)save({cameraX:camera.position.x,cameraY:camera.position.y,cameraZ:camera.position.z});});\\ntinybot.animate((time,delta)=>{mesh.rotation.y+=current.speed*delta;controls.enabled=tinybot.active;controls.update();renderer.render(scene,camera);});\\ncanvas.addEventListener('webglcontextlost',event=>{event.preventDefault();throw new Error('WebGL 上下文丢失，请重新加载。');});\"}"}}
